// FISICA — bilanciamento delle unità (u1, u3, u4, u5, u7) — domande originali
BANK.push(
// ---- Unità 1: metodi, unità di misura, vettori (+34 MC)
{id:"FU101",s:"fis",u:1,q:"Le sette grandezze fondamentali del SI comprendono:",o:["lunghezza, massa, tempo, corrente, temperatura, quantità di sostanza, intensità luminosa","lunghezza, massa, tempo, forza, temperatura, quantità di sostanza, intensità luminosa","lunghezza, massa, tempo, corrente, temperatura, carica elettrica, intensità luminosa","lunghezza, massa, tempo, corrente, energia, quantità di sostanza, intensità luminosa","lunghezza, peso, tempo, corrente, temperatura, quantità di sostanza, pressione"],e:"Tutte le altre grandezze (forza, energia, pressione…) sono derivate.",h:"Le grandezze fondamentali sono quelle da cui si ricavano tutte le altre: forza, energia, carica e pressione sono derivate.",x:"Scarti ogni elenco che contiene forza, carica elettrica, energia, peso o pressione: sono tutte grandezze derivate."},
{id:"FU102",s:"fis",u:1,q:"L'unità di misura SI dell'intensità luminosa è:",o:["la candela","il lumen","il lux","il watt","la diottria"],e:"Il lumen (flusso luminoso) e il lux (illuminamento) sono unità derivate.",h:"È una delle 7 unità fondamentali del SI e ha un nome legato a una fonte di luce.",x:"Lumen e lux sono unità derivate della fotometria; il watt misura la potenza e la diottria il potere di una lente."},
{id:"FU103",s:"fis",u:1,q:"Il joule, espresso in unità fondamentali SI, equivale a:",o:["kg·m²/s²","kg·m/s²","kg·m²/s","kg/(m·s²)","kg·m³/s²"],e:"J = N·m = (kg·m/s²)·m.",h:"1 J = 1 N · 1 m e 1 N = 1 kg·m/s².",x:"kg·m/s² è il newton (manca un metro); kg·m²/s ha un secondo di troppo poco; kg/(m·s²) è il pascal."},
{id:"FU104",s:"fis",u:1,q:"Il watt, espresso in unità fondamentali SI, equivale a:",o:["kg·m²/s³","kg·m²/s²","kg·m/s","kg·m/s³","kg/s"],e:"W = J/s.",h:"1 W = 1 J/s: parti dalle unità del joule e dividi per un secondo.",x:"kg·m²/s² è il joule (manca la divisione per s); kg·m/s è la quantità di moto; kg·m/s³ e kg/s non derivano dal joule."},
{id:"FU105",s:"fis",u:1,q:"Quale coppia di grandezze ha le stesse dimensioni fisiche?",o:["Lavoro ed energia cinetica","Forza e lavoro","Potenza ed energia","Pressione e forza","Impulso ed energia cinetica"],e:"Entrambe si misurano in joule.",h:"Due grandezze hanno le stesse dimensioni se si misurano nella stessa unità.",x:"Forza (N) e lavoro (J) differiscono di un metro; potenza è energia al secondo; pressione è forza su area; impulso (N·s) non è un'energia. Resta la coppia misurata in joule."},
{id:"FU106",s:"fis",u:1,q:"Quale delle seguenti grandezze è adimensionale?",o:["L'indice di rifrazione","La densità","La viscosità","La frequenza","Il periodo di oscillazione"],e:"n = c/v è un rapporto tra velocità. Sono adimensionali anche gli angoli in radianti e il numero di Reynolds.",h:"Una grandezza è adimensionale se è il rapporto di due grandezze dello stesso tipo.",x:"Densità (kg/m³), viscosità (Pa·s), frequenza (s⁻¹) e periodo (s) hanno tutte un'unità di misura. Resta il rapporto tra due velocità."},
{id:"FU107",s:"fis",u:1,q:"Il prefisso 'pico' corrisponde a:",o:["10⁻¹²","10⁻⁹","10⁻¹⁵","10¹²","10⁻⁶"],e:"milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹, pico 10⁻¹², femto 10⁻¹⁵.",h:"La sequenza dei prefissi piccoli va di 3 in 3: milli, micro, nano, pico, femto.",x:"10¹² è tera (esponente positivo, quindi grande); 10⁻⁶ è micro, 10⁻⁹ nano, 10⁻¹⁵ femto."},
{id:"FU108",s:"fis",u:1,q:"Il prefisso 'giga' corrisponde a:",o:["10⁹","10⁶","10¹²","10³","10⁻⁹"],e:"kilo 10³, mega 10⁶, giga 10⁹, tera 10¹².",h:"Prefissi grandi: kilo 10³, mega 10⁶, giga…, tera 10¹².",x:"Giga indica un numero grande: scarti 10⁻⁹. 10³ è kilo, 10⁶ mega, 10¹² tera."},
{id:"FU109",s:"fis",u:1,q:"Un volume di 1 m³ corrisponde a:",o:["10⁶ cm³","10³ cm³","10⁹ cm³","10² cm³","10⁴ cm³"],e:"(100 cm)³ = 10⁶ cm³.",h:"1 m = 100 cm, quindi per i volumi il fattore si eleva al cubo.",x:"10² è il fattore lineare e 10⁴ quello delle aree; 10³ confonde m³ con litri (1 m³ = 1000 L); 10⁹ è troppo grande."},
{id:"FU110",s:"fis",u:1,q:"Una densità di 1 g/cm³ corrisponde a:",o:["1000 kg/m³","1 kg/m³","10 kg/m³","0,001 kg/m³","100 kg/m³"],e:"1 g/cm³ = 10⁻³ kg / 10⁻⁶ m³ = 10³ kg/m³.",h:"1 g = 10⁻³ kg e 1 cm³ = 10⁻⁶ m³: dividi i due fattori.",x:"L'acqua ha densità 1 g/cm³ ed è molto più densa dell'aria (≈1 kg/m³): scarti tutti i valori piccoli."},
{id:"FU111",s:"fis",u:1,q:"Una velocità di 1 m/s corrisponde a:",o:["3,6 km/h","1 km/h","0,36 km/h","36 km/h","60 km/h"],e:"1 m/s × 3600 s/h / 1000 m/km = 3,6 km/h.",h:"In un'ora ci sono 3600 secondi e in un km 1000 metri.",x:"Un valore in km/h è sempre più grande dello stesso valore in m/s: scarti 1 e 0,36. 36 e 60 non corrispondono al fattore 3600/1000."},
{id:"FU112",s:"fis",u:1,q:"Una pressione di 1 atm corrisponde a circa:",o:["1,013·10⁵ Pa","1,013·10³ Pa","760 Pa","1,013·10⁴ Pa","1,013·10⁶ Pa"],e:"1 atm = 760 mmHg ≈ 101 325 Pa ≈ 1,013 bar.",h:"1 atm equivale a 760 mmHg, poco più di 100 000 Pa (circa 1 bar).",x:"760 Pa confonde i mmHg con i pascal; 10³ e 10⁴ Pa sono troppo piccoli; 10⁶ Pa sono circa 10 atmosfere."},
{id:"FU113",s:"fis",u:1,q:"Un'ora corrisponde a:",o:["3600 s","360 s","60 s","36 000 s","6000 s"],e:"60 × 60.",h:"Un'ora ha 60 minuti e ogni minuto ha 60 secondi.",x:"60 s è un minuto e 360 s sono 6 minuti; 36 000 s sono 10 ore. Basta moltiplicare 60 × 60."},
{id:"FU114",s:"fis",u:1,q:"Una lunghezza d'onda di 600 nm corrisponde a:",o:["6·10⁻⁷ m","6·10⁻⁹ m","6·10⁻⁶ m","6·10⁻⁵ m","6·10⁻¹² m"],e:"600 × 10⁻⁹ m = 6·10⁻⁷ m.",h:"1 nm = 10⁻⁹ m; scrivi 600 come 6·10².",x:"6·10⁻⁹ dimentica il fattore 600; 10⁻⁶ e 10⁻⁵ sono valori da micrometri; 10⁻¹² è da picometri."},
{id:"FU115",s:"fis",u:1,q:"L'ordine di grandezza del diametro di un atomo è:",o:["10⁻¹⁰ m","10⁻⁶ m","10⁻¹⁵ m","10⁻³ m","10⁻²⁰ m"],e:"Circa 0,1 nm (1 ångström). Il nucleo è circa 100 000 volte più piccolo (10⁻¹⁵ m).",h:"Un atomo misura circa un ångström (0,1 nm); il nucleo è molto più piccolo.",x:"10⁻¹⁵ m è il nucleo; 10⁻⁶ m è la scala di un batterio; 10⁻³ m si vede a occhio nudo; 10⁻²⁰ m è troppo piccolo anche per un nucleo."},
{id:"FU116",s:"fis",u:1,q:"L'ordine di grandezza del diametro di una cellula eucariotica tipica è:",o:["10⁻⁵ m (decine di micrometri)","10⁻⁷ m (decimi di micrometro)","10⁻³ m (millimetri)","10⁻⁹ m (nanometri)","10⁻⁶ m (un micrometro)"],e:"Le cellule umane misurano in genere tra 10 e 30 μm.",h:"Le cellule umane si vedono al microscopio ottico e misurano qualche decina di micrometri.",x:"Un millimetro si vede a occhio nudo; nanometri e decimi di μm sono la scala di molecole e virus; 1 μm è la taglia di un batterio."},
{id:"FU117",s:"fis",u:1,q:"Il numero 3,2·10⁴ moltiplicato per 2·10⁻⁶ dà:",o:["6,4·10⁻²","6,4·10⁻¹⁰","6,4·10²","1,6·10¹⁰","3,2·10⁻²"],e:"3,2 × 2 = 6,4; 10⁴ × 10⁻⁶ = 10⁻².",h:"Moltiplica i numeri davanti e somma gli esponenti delle potenze di 10.",x:"10⁻¹⁰ si ottiene moltiplicando gli esponenti invece di sommarli; 1,6·10¹⁰ divide. Gli esponenti 4 + (−6) danno −2: resta da controllare il 6,4."},
{id:"FU118",s:"fis",u:1,q:"Il rapporto (8·10⁶)/(4·10⁻³) vale:",o:["2·10⁹","2·10³","32·10³","2·10⁻⁹","4·10⁹"],e:"8/4 = 2; 10⁶/10⁻³ = 10⁹.",h:"Dividi i numeri davanti e sottrai gli esponenti: 6 − (−3).",x:"10³ si ottiene sommando gli esponenti invece di sottrarli; 2·10⁻⁹ inverte il segno. 32·10³ moltiplica invece di dividere; 4·10⁹ sbaglia la divisione 8/4."},
{id:"FU119",s:"fis",u:1,q:"Le cifre significative del numero 0,00450 sono:",o:["3","2","5","6","4"],e:"Gli zeri iniziali non contano, lo zero finale dopo la virgola sì: 4, 5, 0.",h:"Gli zeri a sinistra della prima cifra diversa da zero non contano; quelli finali dopo la virgola sì.",x:"5 e 6 contano anche gli zeri iniziali, che non sono significativi; 2 dimentica lo zero finale, che invece indica la precisione della misura."},
{id:"FU120",s:"fis",u:1,q:"Una misura con errore casuale piccolo ma errore sistematico grande è:",o:["precisa ma poco accurata","accurata e precisa","accurata ma poco precisa","né accurata né precisa per definizione","perfetta"],e:"La precisione riguarda la ripetibilità; l'accuratezza la vicinanza al valore vero.",h:"Precisione = misure vicine tra loro (errore casuale); accuratezza = vicine al valore vero (errore sistematico).",x:"Con errore sistematico grande la misura non può essere accurata: scarti 'accurata' e 'perfetta'. Se l'errore casuale è piccolo, non è vero che non sia precisa."},
{id:"FU121",s:"fis",u:1,q:"Una grandezza vettoriale è caratterizzata da:",o:["modulo, direzione e verso","solo modulo","solo direzione","modulo e unità di misura soltanto","solo verso"],e:"Esempi: spostamento, velocità, forza, campo elettrico.",h:"Pensa a una freccia: per descriverla servono lunghezza, retta su cui giace e da che parte punta.",x:"Un solo modulo descrive una grandezza scalare; direzione o verso da soli non bastano. Serve tutto l'insieme."},
{id:"FU122",s:"fis",u:1,q:"Il vettore opposto di un vettore a:",o:["ha lo stesso modulo e la stessa direzione, ma verso opposto","ha lo stesso modulo e verso opposto, ma direzione perpendicolare","ha modulo opposto, cioè negativo, e la stessa direzione","ha la stessa direzione e lo stesso verso, ma modulo nullo","ha modulo doppio e verso opposto"],e:"a + (−a) = 0.",h:"Sommando un vettore e il suo opposto si deve ottenere il vettore nullo.",x:"Il modulo non può mai essere negativo né nullo né doppio; cambiare direzione darebbe un vettore diverso, che non annulla a."},
{id:"FU123",s:"fis",u:1,q:"Le componenti cartesiane di un vettore di modulo 10 inclinato di 30° rispetto all'asse x sono circa:",o:["(8,7; 5)","(5; 8,7)","(10; 10)","(7,1; 7,1)","(3; 10)"],e:"aₓ = 10·cos 30° ≈ 8,66; a_y = 10·sen 30° = 5.",h:"aₓ = a·cos θ e a_y = a·sen θ; ricorda sen 30° = 0,5.",x:"(10; 10) e (3; 10) avrebbero modulo maggiore di 10; (7,1; 7,1) corrisponde a 45°; (5; 8,7) corrisponde a 60°."},
{id:"FU124",s:"fis",u:1,q:"Il modulo del vettore di componenti (6, 8) è:",o:["10","14","2","48","100"],e:"√(36 + 64) = 10.",h:"Modulo = √(x² + y²).",x:"14 è la somma delle componenti, 2 la differenza, 48 il prodotto; 100 è il modulo al quadrato (manca la radice)."},
{id:"FU125",s:"fis",u:1,q:"La somma dei vettori (2, 3) e (4, −1) è:",o:["(6, 2)","(6, 4)","(−2, 4)","(8, −3)","(2, 2)"],e:"Si sommano le componenti corrispondenti.",h:"Si sommano separatamente le x tra loro e le y tra loro.",x:"(6, 4) ignora il segno meno di −1; (−2, 4) fa la sottrazione; (8, −3) moltiplica le componenti."},
{id:"FU126",s:"fis",u:1,q:"Il prodotto vettoriale di due vettori:",o:["un vettore perpendicolare al piano dei due vettori","uno scalare pari a a·b·cos θ","un vettore parallelo al primo vettore","un vettore nullo se i vettori sono perpendicolari","un vettore che giace nel piano dei due vettori"],e:"Il modulo vale a·b·sen θ e il verso si trova con la regola della mano destra; è nullo per vettori paralleli.",h:"Il prodotto vettoriale dà un vettore il cui modulo è a·b·sen θ; per il verso si usa la regola della mano destra.",x:"a·b·cos θ è il prodotto scalare (uno scalare, non un vettore); con vettori perpendicolari sen θ = 1, quindi non è nullo. Non può giacere nel piano dei vettori."},
{id:"FU127",s:"fis",u:1,q:"Il prodotto scalare di due vettori di modulo 3 e 5 che formano un angolo di 180° vale:",o:["−15","15","0","8","−8"],e:"a·b·cos 180° = 15 × (−1).",h:"Prodotto scalare = a·b·cos θ; quanto vale il coseno di un angolo piatto?",x:"0 vale per vettori perpendicolari, 15 per vettori concordi; 8 e −8 sommano i moduli invece di moltiplicarli."},
{id:"FU128",s:"fis",u:1,q:"Il lavoro di una forza è definito come il prodotto scalare tra forza e spostamento. Per questo il lavoro è:",o:["uno scalare, che può essere positivo, negativo o nullo","un vettore parallelo allo spostamento del corpo","uno scalare, che è sempre positivo o nullo","un vettore parallelo alla forza applicata","uno scalare, sempre negativo se c'è attrito"],e:"Il segno dipende dall'angolo tra forza e spostamento.",h:"Il prodotto scalare dà un numero, e il suo segno dipende dal coseno dell'angolo tra forza e spostamento.",x:"Un prodotto scalare non è mai un vettore: scarti le due opzioni con 'vettore'. Il coseno può essere positivo, nullo o negativo, quindi né 'sempre positivo' né 'sempre negativo'."},
{id:"FU129",s:"fis",u:1,q:"Il radiante è definito come:",o:["l'angolo al centro che sottende un arco lungo quanto il raggio","l'angolo al centro che sottende un arco lungo quanto il diametro","l'angolo al centro che sottende un arco lungo 1 metro","la 360ª parte dell'angolo giro","l'angolo al centro che sottende un arco lungo π volte il raggio"],e:"Un angolo giro vale 2π rad, quindi 1 rad ≈ 57,3°.",h:"In un angolo giro ci sono 2π radianti, cioè una circonferenza intera divisa per il raggio.",x:"La 360ª parte dell'angolo giro è il grado; un arco lungo π volte il raggio è un angolo piatto; un metro fisso non c'entra perché la definizione è un rapporto."},
{id:"FU130",s:"fis",u:1,q:"Un angolo di 90° espresso in radianti vale:",o:["π/2","π","2π","π/4","90π"],e:"180° = π rad.",h:"180° corrispondono a π radianti.",x:"π è un angolo piatto, 2π un angolo giro, π/4 è 45°; 90π non è un angolo sensato."},
{id:"FU131",s:"fis",u:1,q:"Nel grafico di una funzione y = k·x (proporzionalità diretta) si ottiene:",o:["una retta passante per l'origine","una retta che non passa per l'origine","un'iperbole equilatera","una parabola con vertice nell'origine","una retta orizzontale"],e:"La proporzionalità inversa y = k/x dà un'iperbole; y = k·x² una parabola.",h:"Proporzionalità diretta: se x = 0 allora y = 0, e y cresce sempre allo stesso ritmo.",x:"Se x = 0 dà y = 0 la retta deve passare per l'origine; l'iperbole è la proporzionalità inversa e la parabola quella quadratica; una retta orizzontale non dipende da x."},
{id:"FU132",s:"fis",u:1,q:"La pendenza del grafico posizione-tempo di un corpo in un certo istante rappresenta:",o:["la velocità istantanea","l'accelerazione istantanea","lo spazio percorso fino a quell'istante","la velocità media dall'istante iniziale","la forza agente in quell'istante"],e:"La derivata della velocità rispetto al tempo è invece l'accelerazione.",h:"Pendenza = quanto cambia la posizione in un intervallo di tempo piccolissimo.",x:"L'accelerazione è la pendenza del grafico velocità-tempo; lo spazio percorso si legge sull'asse, non dalla pendenza; la velocità media riguarda un intervallo, non un istante."},
{id:"FU133",s:"fis",u:1,q:"L'area sotto il grafico forza-spostamento rappresenta:",o:["il lavoro compiuto dalla forza","la potenza sviluppata dalla forza","l'impulso della forza","la quantità di moto finale","l'energia potenziale iniziale"],e:"Matematicamente è l'integrale della forza nello spostamento. L'area sotto il grafico forza-tempo è invece l'impulso.",h:"Lavoro = forza × spostamento: l'area sotto un grafico è il prodotto delle due grandezze sugli assi.",x:"Impulso = forza × tempo (serve il grafico forza-tempo); la potenza contiene il tempo; quantità di moto ed energia potenziale non sono un prodotto forza × spostamento."},
{id:"FU134",s:"fis",u:1,q:"Una grandezza che raddoppia ogni volta che passa una stessa quantità di tempo cresce in modo:",o:["esponenziale","lineare","quadratico","logaritmico","inversamente proporzionale"],e:"Il decadimento radioattivo è l'esempio speculare: decrescita esponenziale.",h:"Raddoppiare a intervalli regolari significa moltiplicare per 2 ogni volta, non aggiungere sempre la stessa quantità.",x:"La crescita lineare aggiunge sempre la stessa quantità; quella quadratica e quella logaritmica non raddoppiano a intervalli fissi; 'inversamente proporzionale' decresce."},

// ---- Unità 3: fluidi (+6 MC)
{id:"FU301",s:"fis",u:3,q:"La pressione sul fondo di un recipiente pieno di liquido dipende:",o:["dall'altezza e dalla densità del liquido, non dalla forma","dalla quantità totale di liquido nel recipiente","dalla forma del recipiente e dall'altezza del liquido","dall'area del fondo e dalla massa del liquido","dalla densità del liquido e dall'area del fondo"],e:"È il paradosso idrostatico: P = ρ·g·h.",h:"Stevino: P = ρ·g·h, che non contiene né l'area né la forma del recipiente.",x:"La quantità totale di liquido, la forma e l'area del fondo non compaiono nella formula: scarti tutte le opzioni che le citano (è il paradosso idrostatico)."},
{id:"FU302",s:"fis",u:3,q:"Un oggetto immobile che galleggia nel mare è soggetto a:",o:["una spinta di Archimede uguale e opposta al suo peso","una spinta di Archimede maggiore del suo peso","una spinta di Archimede minore del suo peso","solo al proprio peso, senza altre forze","una spinta pari al peso del volume della parte emersa"],e:"Se la risultante non fosse nulla l'oggetto accelererebbe.",h:"Se l'oggetto è immobile, la risultante delle forze su di esso deve essere nulla.",x:"Con spinta maggiore salirebbe e con spinta minore affonderebbe; la spinta esiste sempre su un corpo immerso; la spinta dipende dalla parte immersa, non da quella emersa."},
{id:"FU303",s:"fis",u:3,q:"Due vasi comunicanti contengono lo stesso liquido. All'equilibrio:",o:["il liquido raggiunge la stessa altezza nei due vasi","il livello è più alto nel vaso più largo","il livello è più alto nel vaso più stretto","il liquido si sposta tutto nel vaso più basso","il livello dipende dalla quantità di liquido in ciascuno"],e:"Vale per vasi larghi; per tubi capillari intervengono gli effetti di tensione superficiale.",h:"Con lo stesso liquido, la pressione deve essere uguale alla stessa quota in tutti i vasi comunicanti.",x:"Per Stevino la pressione dipende solo dall'altezza, non dalla larghezza del vaso: scarti 'più alto nel più largo' e 'nel più stretto'. Il liquido non si sposta tutto in un vaso solo."},
{id:"FU304",s:"fis",u:3,q:"La densità relativa di una sostanza è:",o:["il rapporto tra la sua densità e quella dell'acqua (adimensionale)","il rapporto tra la sua massa e il suo volume (in kg/m³)","il rapporto tra il suo peso e il suo volume (in N/m³)","il rapporto tra la sua densità e quella dell'aria (adimensionale)","la sua densità misurata a 0 °C (in kg/m³)"],e:"Una sostanza con densità relativa 2 è due volte più densa dell'acqua.",h:"'Relativa' significa confrontata con una sostanza di riferimento: per liquidi e solidi è l'acqua.",x:"Massa/volume è la densità assoluta (con unità); peso/volume è il peso specifico; il riferimento è l'acqua, non l'aria; la temperatura di misura non cambia la definizione."},
{id:"FU305",s:"fis",u:3,q:"In un'arteria il sangue scorre in regime laminare. Raddoppiando la lunghezza del tratto considerato, a parità di portata, la caduta di pressione:",o:["raddoppia","si dimezza","resta uguale","quadruplica","si riduce di 16 volte"],e:"Per Poiseuille ΔP = Q·R con R ∝ L.",h:"Poiseuille: ΔP = Q·R, con R ∝ L.",x:"Un tratto più lungo oppone più resistenza: scarti 'si dimezza' e 'resta uguale'. La lunghezza compare alla prima potenza: niente 4 o 16."},
{id:"FU306",s:"fis",u:3,q:"La sfigmomanometria (misura della pressione arteriosa con il bracciale) si basa sull'ascolto dei suoni di Korotkoff, prodotti da:",o:["il flusso turbolento del sangue nell'arteria parzialmente compressa","il flusso laminare del sangue nell'arteria parzialmente compressa","la vibrazione delle valvole cardiache trasmessa lungo l'arteria","il battito del bracciale contro la parete del braccio","l'arresto completo del flusso nell'arteria chiusa"],e:"Quando la pressione del bracciale scende sotto quella sistolica il sangue passa a getti, in regime turbolento e quindi rumoroso.",h:"Un flusso ordinato è silenzioso; un flusso con vortici è rumoroso.",x:"Il flusso laminare non produce suoni; le valvole si ascoltano sul torace, non sotto il bracciale; con l'arteria chiusa non c'è flusso e quindi non c'è suono."},

// ---- Unità 4: onde (+35 MC)
{id:"FU401",s:"fis",u:4,q:"Un'onda meccanica trasporta:",o:["energia, senza trasporto netto di materia","materia, senza trasporto netto di energia","sia energia sia materia nella direzione di propagazione","solo quantità di moto, senza energia","né energia né materia"],e:"Le particelle del mezzo oscillano intorno alla posizione di equilibrio.",h:"Pensa a un'onda nello stadio: si propaga lungo gli spalti, ma ogni persona resta al suo posto.",x:"Le particelle oscillano attorno alla posizione di equilibrio senza spostarsi: scarti 'trasporta materia'. Un'onda trasporta energia, quindi scarti 'né energia' e 'senza energia'."},
{id:"FU402",s:"fis",u:4,q:"La relazione tra velocità di propagazione v, lunghezza d'onda λ e frequenza f è:",o:["v = λ·f","v = λ/f","v = f/λ","v = λ + f","v = λ²·f"],e:"In un periodo l'onda avanza di una lunghezza d'onda: v = λ/T = λ·f.",h:"In un periodo T l'onda avanza di una lunghezza d'onda: v = λ/T.",x:"Controlla le unità: v deve essere in m/s. λ/f dà m·s, f/λ dà 1/(m·s), λ + f somma grandezze diverse e λ²·f dà m²/s."},
{id:"FU403",s:"fis",u:4,q:"La pulsazione ω di un'onda di frequenza 50 Hz è circa:",o:["314 rad/s","50 rad/s","8 rad/s","100 rad/s","3,14 rad/s"],e:"ω = 2πf.",h:"ω = 2π·f.",x:"50 rad/s confonde ω con f; 8 rad/s divide per 2π invece di moltiplicare; 100 dimentica π; 3,14 dimentica la frequenza."},
{id:"FU404",s:"fis",u:4,q:"Un'onda ha periodo 4 ms. La sua frequenza è:",o:["250 Hz","4 Hz","0,25 Hz","4000 Hz","25 Hz"],e:"f = 1/T = 1/0,004 s.",h:"f = 1/T, con T in secondi (4 ms = 0,004 s).",x:"4 Hz e 0,25 Hz non convertono i millisecondi; 4000 Hz moltiplica; 25 Hz sbaglia la conversione di un fattore 10."},
{id:"FU405",s:"fis",u:4,q:"Il vettore d'onda k di un'onda armonica ha modulo:",o:["2π/λ","λ/2π","2π·f","1/T","v·λ"],e:"Indica la direzione di propagazione; insieme a ω compare nell'equazione y = A·sen(kx − ωt).",h:"k sta a λ come ω sta a T: k = 2π diviso per la lunghezza d'onda.",x:"2π·f è la pulsazione ω; 1/T è la frequenza; λ/2π è l'inverso; v·λ non ha le dimensioni di 1/m."},
{id:"FU406",s:"fis",u:4,q:"Nell'equazione di un'onda y = A·sen(kx − ωt), la grandezza A rappresenta:",o:["l'ampiezza","la frequenza","la lunghezza d'onda","la velocità","la fase iniziale"],e:"È lo spostamento massimo dalla posizione di equilibrio.",h:"Il seno oscilla tra −1 e +1: il fattore davanti dà lo spostamento massimo.",x:"La frequenza e la lunghezza d'onda sono contenute in ω e k dentro il seno; la velocità è ω/k; la fase iniziale si aggiungerebbe dentro l'argomento."},
{id:"FU407",s:"fis",u:4,q:"La velocità di un'onda su una corda tesa aumenta:",o:["aumentando la tensione della corda","aumentando la massa per unità di lunghezza","aumentando l'ampiezza","diminuendo la tensione","aumentando la frequenza della sorgente"],e:"v = √(T/μ): dipende solo dalle proprietà del mezzo.",h:"Su una corda tesa v = √(T/μ), con T tensione e μ massa per unità di lunghezza.",x:"Aumentare μ o diminuire la tensione riduce la velocità; ampiezza e frequenza della sorgente non cambiano la velocità, che dipende solo dal mezzo."},
{id:"FU408",s:"fis",u:4,q:"La velocità del suono in un gas, all'aumentare della temperatura:",o:["aumenta","diminuisce","resta costante","si annulla","dipende solo dalla frequenza"],e:"In aria passa da circa 331 m/s a 0 °C a circa 343 m/s a 20 °C.",h:"Nei gas il suono viaggia grazie agli urti tra molecole: più sono veloci, più è veloce il suono.",x:"La velocità del suono dipende dal mezzo e dalla sua temperatura, non dalla frequenza; aumentando T le molecole sono più veloci, quindi non può diminuire né restare costante."},
{id:"FU409",s:"fis",u:4,q:"Un'onda sonora di frequenza 1000 Hz in aria (340 m/s) ha lunghezza d'onda:",o:["0,34 m","3,4 m","34 m","0,034 m","340 m"],e:"λ = 340/1000.",h:"λ = v / f.",x:"3,4, 34 e 340 m sbagliano la divisione di un fattore 10 o più; 0,034 m sarebbe un suono a 10 000 Hz."},
{id:"FU410",s:"fis",u:4,q:"Gli ultrasuoni usati in ecografia (circa 1-15 MHz) hanno nei tessuti (circa 1540 m/s) lunghezze d'onda dell'ordine di:",o:["decimi di millimetro","metri","centimetri","micrometri","nanometri"],e:"A 5 MHz λ ≈ 0,3 mm: lunghezze d'onda piccole permettono una buona risoluzione.",h:"λ = v / f: dividi 1540 m/s per qualche milione di hertz.",x:"Metri e centimetri sono lunghezze d'onda di suoni udibili; micrometri e nanometri richiederebbero frequenze migliaia di volte più alte."},
{id:"FU411",s:"fis",u:4,q:"In ecografia, aumentando la frequenza degli ultrasuoni:",o:["migliora la risoluzione ma diminuisce la profondità esplorabile","migliora sia la risoluzione sia la profondità esplorabile","peggiora la risoluzione ma aumenta la profondità esplorabile","peggiora sia la risoluzione sia la profondità esplorabile","migliora la risoluzione e la profondità non cambia"],e:"Per gli organi profondi si usano frequenze più basse; per tessuti superficiali (tiroide, tendini) più alte.",h:"Frequenza più alta significa lunghezza d'onda più corta (più dettagli) ma anche maggiore assorbimento nei tessuti.",x:"Le alte frequenze vengono assorbite di più, quindi la profondità diminuisce: scarti le opzioni con profondità maggiore o invariata. La risoluzione migliora, non peggiora."},
{id:"FU412",s:"fis",u:4,q:"L'altezza di un suono (acuto o grave) dipende soprattutto dalla sua:",o:["frequenza","ampiezza","velocità","durata","direzione"],e:"L'intensità percepita (forte o debole) dipende dall'ampiezza; il timbro dalla composizione in armoniche.",h:"Un suono acuto ha molte oscillazioni al secondo, uno grave poche.",x:"L'ampiezza determina il volume; la velocità dipende dal mezzo; durata e direzione non cambiano la nota percepita."},
{id:"FU413",s:"fis",u:4,q:"Il timbro di un suono, che permette di distinguere strumenti diversi che suonano la stessa nota:",o:["dipende dalla forma d'onda, cioè dalle armoniche","dipende solo dalla frequenza fondamentale","dipende solo dall'intensità del suono","dipende dalla velocità del suono nell'aria","dipende dalla lunghezza d'onda fondamentale"],e:"Due strumenti con la stessa fondamentale hanno armoniche con intensità diverse.",h:"Un violino e un flauto possono suonare la stessa nota alla stessa intensità e restare distinguibili.",x:"La stessa nota significa la stessa fondamentale e la stessa lunghezza d'onda; l'intensità determina il volume; la velocità del suono è la stessa per tutti gli strumenti."},
{id:"FU414",s:"fis",u:4,q:"Un suono di 120 dB, rispetto a uno di 60 dB, ha intensità:",o:["10⁶ volte maggiore","2 volte maggiore","60 volte maggiore","10¹² volte maggiore","1000 volte maggiore"],e:"60 dB di differenza = fattore 10⁶.",h:"Ogni 10 dB l'intensità si moltiplica per 10.",x:"2 e 60 volte trattano i decibel come grandezze lineari; 10¹² corrisponde a 120 dB rispetto alla soglia, non a 60 dB di differenza; 1000 volte corrisponde a 30 dB."},
{id:"FU415",s:"fis",u:4,q:"La soglia del dolore per l'orecchio umano si trova intorno a:",o:["120-130 dB","0 dB","40-50 dB","60-70 dB","200 dB"],e:"Corrisponde a circa 1-10 W/m².",h:"Una conversazione è circa 60 dB e un concerto rock circa 110 dB: la soglia del dolore è un po' sopra.",x:"0 dB è la soglia di udibilità; 40-70 dB sono suoni quotidiani (biblioteca, conversazione); 200 dB è un'onda d'urto ben oltre il dolore."},
{id:"FU416",s:"fis",u:4,q:"Raddoppiando l'intensità di un suono, il livello sonoro aumenta di circa:",o:["3 dB","2 dB","10 dB","20 dB","6 dB"],e:"10·log 2 ≈ 3 dB.",h:"Δβ = 10·log(I₂/I₁), e log 2 ≈ 0,3.",x:"10 dB corrisponde a un fattore 10, 20 dB a 100; 2 dB tratta i dB come lineari; 6 dB corrisponde a un fattore 4."},
{id:"FU417",s:"fis",u:4,q:"Per una sorgente puntiforme, passando da 1 m a 10 m di distanza il livello sonoro diminuisce di:",o:["20 dB","10 dB","2 dB","100 dB","3 dB"],e:"L'intensità diminuisce di 100 volte (1/r²): −20 dB.",h:"Intensità ∝ 1/r²: a distanza 10 volte maggiore l'intensità è 100 volte minore.",x:"10 dB dimentica il quadrato; 3 dB corrisponde a un dimezzamento; 2 dB tratta i dB come lineari; 100 dB è la variazione dell'intensità scambiata per decibel."},
{id:"FU418",s:"fis",u:4,q:"Le onde stazionarie si formano per:",o:["sovrapposizione di due onde uguali che si propagano in versi opposti","sovrapposizione di due onde uguali che si propagano nello stesso verso","sovrapposizione di due onde di frequenza leggermente diversa","diffrazione di un'onda attraverso una fenditura stretta","riflessione di un'onda su un mezzo che la assorbe"],e:"Si osservano in corde fisse agli estremi e in canne d'organo.",h:"Pensa a un'onda su una corda fissata che si riflette all'estremità e torna indietro sovrapponendosi a sé stessa.",x:"Onde nello stesso verso danno un'onda che viaggia; frequenze leggermente diverse danno i battimenti; diffrazione e assorbimento sono fenomeni diversi."},
{id:"FU419",s:"fis",u:4,q:"Una corda lunga 1 m fissata agli estremi vibra nella sua armonica fondamentale a 200 Hz. La velocità delle onde sulla corda è:",o:["400 m/s","200 m/s","100 m/s","800 m/s","2 m/s"],e:"λ = 2L = 2 m; v = λ·f = 400 m/s.",h:"Nella fondamentale λ = 2L; poi v = λ·f.",x:"200 m/s usa λ = L; 100 m/s usa λ = L/2; 800 m/s usa λ = 4L; 2 m/s è la lunghezza d'onda in metri."},
{id:"FU420",s:"fis",u:4,q:"La seconda armonica di una corda fissata agli estremi ha frequenza:",o:["doppia della fondamentale","uguale alla fondamentale","metà della fondamentale","quadrupla della fondamentale","tripla della fondamentale"],e:"Le armoniche di una corda sono fₙ = n·f₁.",h:"Le armoniche di una corda fissata agli estremi hanno frequenze fₙ = n·f₁.",x:"Le armoniche superiori hanno frequenza maggiore della fondamentale: scarti 'uguale' e 'metà'. La seconda armonica corrisponde a n = 2."},
{id:"FU421",s:"fis",u:4,q:"Due onde di uguale ampiezza A che interferiscono in modo costruttivo producono un'onda di ampiezza:",o:["2A","A","0","A²","√2·A"],e:"In fase le ampiezze si sommano; l'intensità diventa 4 volte quella di una singola onda.",h:"In fase le ampiezze si sommano direttamente.",x:"0 è l'interferenza distruttiva; A ignora la seconda onda; A² non ha le dimensioni di un'ampiezza; √2·A vale per onde incoerenti (somma delle intensità)."},
{id:"FU422",s:"fis",u:4,q:"Due suoni di frequenza molto vicina (es. 440 Hz e 442 Hz) sovrapposti producono:",o:["battimenti, con variazioni periodiche dell'intensità a 2 Hz","battimenti, con variazioni periodiche dell'intensità a 441 Hz","un suono a 882 Hz, somma delle due frequenze","un'onda stazionaria a 2 Hz udibile come nota","silenzio, per interferenza distruttiva"],e:"La frequenza dei battimenti è la differenza delle frequenze. I musicisti li usano per accordare gli strumenti.",h:"La frequenza dei battimenti è la differenza delle due frequenze.",x:"441 Hz è la media, cioè la nota che si sente, non la frequenza dei battimenti; non si somma a 882 Hz; 2 Hz non è udibile come nota; le onde non si annullano del tutto."},
{id:"FU423",s:"fis",u:4,q:"La riflessione del suono su una parete lontana che si percepisce come ripetizione distinta si chiama:",o:["eco","riverbero","rifrazione","diffrazione","risonanza"],e:"Per percepire un'eco distinta servono almeno circa 0,1 s di ritardo, cioè una parete a più di 17 m.",h:"È la ripetizione distinta che senti gridando davanti a una montagna lontana.",x:"Il riverbero è un prolungamento del suono con riflessioni ravvicinate, non una ripetizione distinta; rifrazione, diffrazione e risonanza sono altri fenomeni."},
{id:"FU424",s:"fis",u:4,q:"Un pipistrello emette un ultrasuono e ne riceve l'eco dopo 0,02 s. Con v = 340 m/s, l'ostacolo dista:",o:["3,4 m","6,8 m","17 m","0,34 m","1,7 m"],e:"Il suono percorre andata e ritorno: d = v·t/2 = 340 × 0,02/2.",h:"Il suono va e torna: la distanza è metà dello spazio percorso, d = v·t/2.",x:"6,8 m dimentica di dividere per 2; 17 m e 0,34 m sbagliano la moltiplicazione; 1,7 m divide per 4."},
{id:"FU425",s:"fis",u:4,q:"L'ecografia ricostruisce la profondità di una struttura misurando:",o:["il tempo che l'eco impiega a tornare alla sonda","la variazione di frequenza dell'eco rispetto all'onda emessa","l'intensità dell'eco che torna alla sonda","la frequenza dell'onda emessa dalla sonda","la lunghezza d'onda dell'onda emessa"],e:"Si assume una velocità media nei tessuti di 1540 m/s.",h:"Si assume che il suono viaggi nei tessuti a velocità nota (≈ 1540 m/s): da cosa si ricava la distanza?",x:"La variazione di frequenza misura la velocità (Doppler), non la profondità; l'intensità dell'eco indica il tipo di tessuto; frequenza e lunghezza d'onda emesse sono fissate dalla sonda."},
{id:"FU426",s:"fis",u:4,q:"Nell'ecodoppler, se il sangue si allontana dalla sonda, la frequenza dell'eco ricevuta è:",o:["minore di quella emessa","maggiore di quella emessa","uguale a quella emessa","nulla","doppia"],e:"Dal valore dello spostamento di frequenza si calcola la velocità del sangue.",h:"Effetto Doppler: allontanamento → frequenza percepita minore.",x:"Una frequenza maggiore si avrebbe con sangue che si avvicina; uguale solo se il sangue fosse fermo rispetto alla sonda; la frequenza non diventa nulla né doppia."},
{id:"FU427",s:"fis",u:4,q:"Un osservatore che si avvicina a una sorgente sonora ferma percepisce:",o:["una frequenza maggiore di quella emessa","una frequenza minore di quella emessa","la stessa frequenza, perché la sorgente è ferma","una lunghezza d'onda maggiore di quella emessa","una velocità del suono minore"],e:"L'effetto Doppler si verifica sia se si muove la sorgente sia se si muove l'osservatore.",h:"Avvicinandosi, l'osservatore incontra le creste più spesso del normale.",x:"Una frequenza minore si ha allontanandosi; l'effetto Doppler c'è anche se si muove l'osservatore; la lunghezza d'onda emessa da una sorgente ferma non cambia e la velocità del suono rispetto all'aria neppure."},
{id:"FU428",s:"fis",u:4,q:"La risonanza si verifica quando:",o:["la frequenza della sollecitazione coincide con una frequenza propria e l'ampiezza cresce","la frequenza della sollecitazione è doppia di quella propria e l'ampiezza si annulla","due onde in opposizione di fase si annullano a vicenda","un'onda passa da un mezzo a un altro cambiando velocità","la frequenza della sollecitazione coincide con quella propria e l'ampiezza diminuisce"],e:"Esempi: il bicchiere che si rompe con una nota, l'amplificazione nella cassa armonica di una chitarra.",h:"Pensa all'altalena: si spinge al ritmo giusto (la sua frequenza propria) e oscilla sempre più ampia.",x:"A frequenza doppia non si ha risonanza; l'annullamento in opposizione di fase è interferenza distruttiva; il cambio di mezzo è rifrazione; in risonanza l'ampiezza cresce."},
{id:"FU429",s:"fis",u:4,q:"Le onde sonore non possono essere polarizzate perché:",o:["nei fluidi sono onde longitudinali","nei fluidi sono onde trasversali","sono onde elettromagnetiche longitudinali","hanno frequenza troppo bassa","si propagano troppo lentamente"],e:"La polarizzazione è tipica delle onde trasversali, come la luce.",h:"Si possono polarizzare solo le onde in cui l'oscillazione è perpendicolare alla direzione di propagazione.",x:"Nei fluidi il suono non è trasversale; il suono non è un'onda elettromagnetica; frequenza e velocità non c'entrano con la polarizzazione."},
{id:"FU430",s:"fis",u:4,q:"L'intensità di un'onda sonora a una certa distanza dalla sorgente è 10⁻⁶ W/m². Il livello sonoro è:",o:["60 dB","6 dB","−60 dB","120 dB","10 dB"],e:"10·log(10⁻⁶/10⁻¹²) = 60 dB.",h:"β = 10·log(I/I₀), con I₀ = 10⁻¹² W/m².",x:"6 dB dimentica il 10; −60 dB inverte il rapporto; 120 dB corrisponde a 1 W/m²; 10 dB a 10⁻¹¹ W/m²."},
{id:"FU431",s:"fis",u:4,q:"La potenza trasportata da un'onda sonora che attraversa una superficie di 2 m² con intensità 0,01 W/m² è:",o:["0,02 W","0,005 W","2 W","0,01 W","200 W"],e:"P = I·A.",h:"Potenza = intensità × area.",x:"0,005 W divide invece di moltiplicare; 0,01 W ignora l'area; 2 e 200 W sbagliano gli ordini di grandezza."},
{id:"FU432",s:"fis",u:4,q:"La coclea dell'orecchio interno distingue frequenze diverse perché:",o:["punti diversi della membrana basilare risuonano a frequenze diverse","tutta la membrana basilare vibra insieme a qualsiasi frequenza","contiene cristalli piezoelettrici tarati su frequenze diverse","la base della coclea risponde ai suoni gravi e l'apice agli acuti","misura lo spostamento Doppler dell'onda nel liquido cocleare"],e:"La base della coclea risponde ai suoni acuti, l'apice ai gravi.",h:"La membrana basilare cambia larghezza e rigidità lungo la coclea, quindi ogni punto ha la sua frequenza di risonanza.",x:"Se vibrasse tutta insieme non distinguerebbe le frequenze; non contiene cristalli piezoelettrici; la base risponde agli acuti, non ai gravi; il Doppler non c'entra."},
{id:"FU433",s:"fis",u:4,q:"Un oscillatore armonico (massa-molla) è il modello base delle onde perché:",o:["ogni punto del mezzo attraversato da un'onda armonica oscilla di moto armonico","ogni punto del mezzo attraversato da un'onda si sposta insieme all'onda","le onde si propagano sempre lungo traiettorie circolari","l'energia di un'onda è sempre uguale a quella di una molla","le onde armoniche hanno ampiezza costante solo se c'è una molla"],e:"Un'onda è una perturbazione che si propaga facendo oscillare in successione i punti del mezzo.",h:"Un'onda armonica fa oscillare in successione ogni punto del mezzo attorno alla sua posizione di equilibrio.",x:"I punti del mezzo non viaggiano con l'onda; le onde non seguono traiettorie circolari; l'energia non è 'sempre uguale a una molla' e le onde armoniche esistono anche senza molle."},
{id:"FU434",s:"fis",u:4,q:"Le onde sismiche P (primarie), che arrivano per prime, sono:",o:["longitudinali, e si propagano anche nei liquidi","trasversali, e non attraversano i liquidi","longitudinali, e non attraversano i liquidi","trasversali, e si propagano anche nei liquidi","onde di superficie lente e distruttive"],e:"Le onde S, trasversali e più lente, non attraversano il nucleo esterno liquido della Terra.",h:"Le onde P sono onde di compressione, come il suono: si propagano in solidi, liquidi e gas.",x:"Le onde trasversali (S) non attraversano i liquidi e arrivano dopo; le onde di superficie sono le più lente; le onde di compressione attraversano anche i liquidi."},
{id:"FU435",s:"fis",u:4,q:"Raddoppiando la frequenza di un'onda in un mezzo, a parità di velocità di propagazione, la lunghezza d'onda:",o:["si dimezza","raddoppia","resta uguale","quadruplica","si riduce a un quarto"],e:"λ = v/f.",h:"λ = v / f: a velocità costante λ e f sono inversamente proporzionali.",x:"Aumentando f la lunghezza d'onda diminuisce: scarti 'raddoppia', 'quadruplica' e 'resta uguale'. Un quarto eleva al quadrato."},

// ---- Unità 5: termodinamica (+22 MC)
{id:"FU501",s:"fis",u:5,q:"Due corpi a contatto termico raggiungono l'equilibrio quando hanno:",o:["la stessa temperatura","la stessa quantità di calore","la stessa massa","la stessa energia interna","lo stesso calore specifico"],e:"È il principio zero della termodinamica, alla base dei termometri.",h:"È il principio zero della termodinamica, quello su cui si basa il termometro.",x:"Il calore non è una proprietà posseduta dai corpi ma energia in transito; massa, energia interna e calore specifico possono restare diversi anche all'equilibrio."},
{id:"FU502",s:"fis",u:5,q:"Una temperatura di 100 °F corrisponde a circa:",o:["38 °C","100 °C","212 °C","56 °C","73 °C"],e:"T(°C) = (T(°F) − 32)·5/9 = 68 × 5/9 ≈ 37,8 °C.",h:"T(°C) = (T(°F) − 32) × 5/9.",x:"100 °C è il punto di ebollizione (212 °F); 212 °C confonde le scale; 56 °C dimentica di sottrarre 32; 73 °C sbaglia il fattore. 100 °F è circa la temperatura di una persona con la febbre."},
{id:"FU503",s:"fis",u:5,q:"Una variazione di temperatura di 10 °C corrisponde a una variazione di:",o:["10 K","283 K","−263 K","50 K","18 K"],e:"Le scale Celsius e Kelvin hanno gradi della stessa ampiezza: cambia solo lo zero.",h:"Celsius e Kelvin hanno gradi della stessa ampiezza: cambia solo lo zero della scala.",x:"283 K è la temperatura assoluta corrispondente a 10 °C, non una variazione; −263 K non ha senso; 18 è la variazione in °F; 50 K non c'entra."},
{id:"FU504",s:"fis",u:5,q:"Il calore specifico dell'acqua è circa:",o:["4186 J/(kg·K)","418,6 J/(kg·K)","1 J/(kg·K)","41,86 J/(kg·K)","4,186 J/(kg·K)"],e:"Cioè 1 kcal/(kg·K) = 1 cal/(g·K): è tra i più alti tra le sostanze comuni.",h:"Ricorda: 1 caloria scalda 1 g d'acqua di 1 °C, e 1 cal ≈ 4,186 J.",x:"Per 1 kg servono 1000 volte di più che per 1 g: 4,186 J/(g·K) diventa 4186 J/(kg·K). Gli altri valori sbagliano una o più potenze di 10."},
{id:"FU505",s:"fis",u:5,q:"Due corpi con la stessa massa ricevono la stessa quantità di calore. Il primo ha calore specifico doppio del secondo. La variazione di temperatura del primo è:",o:["la metà di quella del secondo","il doppio di quella del secondo","uguale a quella del secondo","un quarto di quella del secondo","quattro volte quella del secondo"],e:"ΔT = Q/(m·c).",h:"ΔT = Q / (m·c).",x:"Con calore specifico maggiore la temperatura sale di meno: scarti 'doppio', 'uguale' e 'quattro volte'. 'Un quarto' eleva il fattore al quadrato."},
{id:"FU506",s:"fis",u:5,q:"Un calorimetro serve a:",o:["misurare il calore scambiato in un processo","misurare la temperatura assoluta di un corpo","misurare il calore latente solo dei gas","misurare la capacità termica dell'aria","misurare l'energia interna di un gas ideale"],e:"Si basa sullo scambio di calore con una massa nota d'acqua in un recipiente isolato.",h:"Il nome viene da 'calore' + 'misurare'.",x:"La temperatura si misura con un termometro; il calorimetro funziona per qualsiasi sostanza, non solo per i gas; capacità termica dell'aria ed energia interna non sono il suo scopo."},
{id:"FU507",s:"fis",u:5,q:"Durante l'ebollizione dell'acqua a pressione costante, il calore fornito:",o:["fa passare le molecole allo stato di vapore e la temperatura resta costante","fa aumentare la temperatura dell'acqua fino al completamento","fa passare le molecole allo stato di vapore e la temperatura aumenta","fa aumentare l'energia cinetica media delle molecole","viene ceduto all'ambiente e la temperatura diminuisce"],e:"È il calore latente di vaporizzazione.",h:"Durante un passaggio di stato il calore serve a separare le molecole, non ad agitarle di più.",x:"Durante l'ebollizione a pressione costante la temperatura resta costante: scarti le opzioni in cui aumenta o diminuisce. Se la temperatura non cambia, l'energia cinetica media non aumenta."},
{id:"FU508",s:"fis",u:5,q:"Per trasformare 1 kg di acqua a 100 °C in vapore a 100 °C servono circa:",o:["2260 kJ","418,6 kJ","334 kJ","4,186 kJ","100 kJ"],e:"Il calore latente di vaporizzazione è circa 5 volte il calore necessario per scaldare la stessa acqua da 0 a 100 °C.",h:"Serve il calore latente di vaporizzazione dell'acqua, il più grande tra i calori di trasformazione dell'acqua.",x:"334 kJ è il calore latente di fusione; 418,6 kJ scalda 1 kg d'acqua da 0 a 100 °C; 4,186 e 100 kJ sono troppo piccoli."},
{id:"FU509",s:"fis",u:5,q:"Un buon isolante termico ha:",o:["bassa conducibilità termica","alta conducibilità termica","alto calore specifico soltanto","alta densità","alta conducibilità elettrica"],e:"L'aria ferma è un ottimo isolante: per questo isolano piumini, lana e materiali porosi.",h:"Un isolante lascia passare poco calore per conduzione.",x:"Alta conducibilità è la proprietà dei conduttori (metalli); il calore specifico e la densità non definiscono un isolante; la conducibilità elettrica non c'entra."},
{id:"FU510",s:"fis",u:5,q:"Un thermos riduce gli scambi di calore perché:",o:["il vuoto blocca conduzione e convezione, l'argentatura riduce l'irraggiamento","il vuoto blocca l'irraggiamento, l'argentatura riduce conduzione e convezione","il metallo delle pareti conduce poco il calore e lo trattiene","contiene un liquido refrigerante che assorbe il calore","l'aria nell'intercapedine blocca l'irraggiamento e la conduzione"],e:"Ognuno dei tre meccanismi di trasmissione del calore viene limitato.",h:"Conduzione e convezione richiedono materia; l'irraggiamento no, ma può essere riflesso.",x:"Il vuoto non può bloccare l'irraggiamento (la luce attraversa il vuoto); nel thermos l'intercapedine è vuota, non piena d'aria; non contiene refrigeranti; il metallo è un buon conduttore."},
{id:"FU511",s:"fis",u:5,q:"In una trasformazione isobara di un gas ideale, se il volume raddoppia, la temperatura assoluta:",o:["raddoppia","si dimezza","resta costante","quadruplica","diminuisce di 273 K"],e:"V/T = costante a pressione costante.",h:"A pressione costante V/T è costante (legge di Gay-Lussac / Charles).",x:"Se V raddoppia anche T deve raddoppiare: scarti 'si dimezza', 'costante' e 'diminuisce'. Quadruplica eleva al quadrato."},
{id:"FU512",s:"fis",u:5,q:"Un gas ideale si espande in un'isoterma. Il calore che assorbe è:",o:["uguale al lavoro che compie","nullo","uguale alla variazione di energia interna","maggiore del lavoro","negativo"],e:"ΔU = 0 → Q = L.",h:"Isoterma di un gas ideale: ΔU = 0, quindi per il primo principio Q = L.",x:"Q = 0 è l'adiabatica; ΔU vale 0, non Q; se Q fosse maggiore di L l'energia interna aumenterebbe; in un'espansione il gas assorbe calore, quindi non è negativo."},
{id:"FU513",s:"fis",u:5,q:"Nel piano P-V, un'isoterma di un gas ideale è rappresentata da:",o:["un ramo di iperbole","una retta orizzontale","una retta verticale","una parabola","una circonferenza"],e:"P·V = costante. L'isobara è orizzontale, l'isocora verticale; l'adiabatica è più ripida dell'isoterma.",h:"Boyle: P·V = costante.",x:"La retta orizzontale è l'isobara, quella verticale l'isocora; P = cost/V non è una parabola né una circonferenza."},
{id:"FU514",s:"fis",u:5,q:"Un gas viene compresso rapidamente in modo adiabatico (es. in una pompa per bicicletta). La sua temperatura:",o:["aumenta","diminuisce","resta costante","si annulla","oscilla"],e:"Q = 0, il lavoro fatto sul gas aumenta la sua energia interna.",h:"Adiabatica: Q = 0, quindi il lavoro fatto sul gas va tutto in energia interna.",x:"Comprimendo si fa lavoro sul gas, che si scalda: scarti 'diminuisce', 'resta costante', 'si annulla'. Non oscilla perché il processo ha un verso definito."},
{id:"FU515",s:"fis",u:5,q:"Il lavoro compiuto da un gas in una trasformazione isocora è:",o:["nullo","massimo","uguale al calore assorbito","uguale a P·V","infinito"],e:"Senza variazione di volume non c'è lavoro meccanico.",h:"L = P·ΔV: in un'isocora ΔV = 0.",x:"Senza variazione di volume il lavoro non può essere massimo né infinito; il calore assorbito va tutto in energia interna, non in lavoro; P·V non è un lavoro."},
{id:"FU516",s:"fis",u:5,q:"Un frigorifero trasferisce calore dall'interno freddo all'ambiente più caldo:",o:["consumando lavoro, nel rispetto del secondo principio","spontaneamente, senza consumare alcuna energia","consumando lavoro, ma violando il secondo principio","creando freddo, cioè energia negativa, dal nulla","cedendo all'ambiente meno calore di quello estratto"],e:"Il calore ceduto all'ambiente è la somma del calore estratto e del lavoro del compressore.",h:"Il calore va spontaneamente dal caldo al freddo: per invertire il verso serve un compressore.",x:"Senza lavoro il processo violerebbe il secondo principio; consumando lavoro non lo viola; il freddo non è energia negativa; il calore ceduto all'esterno è maggiore di quello estratto (si aggiunge il lavoro)."},
{id:"FU517",s:"fis",u:5,q:"Il rendimento di una macchina termica reale che lavora tra le stesse temperature di una macchina di Carnot è:",o:["minore di quello della macchina di Carnot","maggiore di quello della macchina di Carnot","uguale a quello della macchina di Carnot","uguale al 100% se gli attriti sono trascurabili","maggiore o minore a seconda del gas usato"],e:"Le irreversibilità (attriti, scambi di calore con salti di temperatura) riducono il rendimento.",h:"Il rendimento di Carnot è il massimo possibile tra due temperature.",x:"Nessuna macchina reale supera o eguaglia Carnot, perché ha attriti e irreversibilità; il 100% è impossibile; il rendimento di Carnot non dipende dal gas."},
{id:"FU518",s:"fis",u:5,q:"Nelle centrali termoelettriche il calore viene trasformato in energia elettrica con rendimenti tipici intorno al:",o:["35-45%","100%","90-99%","70-80%","5-10%"],e:"Il calore residuo viene disperso (torri di raffreddamento) o recuperato per il teleriscaldamento.",h:"Una centrale termica non può superare il rendimento di Carnot, e le perdite reali sono notevoli.",x:"100% e 90-99% sono impossibili per il secondo principio; 70-80% supera i limiti pratici di Carnot per queste temperature; 5-10% è troppo basso per una centrale moderna."},
{id:"FU519",s:"fis",u:5,q:"Dal punto di vista statistico, l'entropia di un sistema è legata:",o:["al numero di microstati compatibili con lo stato macroscopico","al numero di molecole presenti, indipendentemente dallo stato","alla sola temperatura del sistema, indipendentemente dal volume","all'energia cinetica media delle sue molecole","al numero di stati macroscopici possibili del sistema"],e:"Formula di Boltzmann: S = k·ln W.",h:"Formula di Boltzmann: S = k·ln W, dove W conta i modi in cui si può realizzare lo stesso stato macroscopico.",x:"L'entropia dipende dallo stato (non solo dal numero di molecole) e anche dal volume; l'energia cinetica media è la temperatura; si contano i microstati, non i macrostati."},
{id:"FU520",s:"fis",u:5,q:"Quando il ghiaccio fonde a 0 °C, la sua entropia:",o:["aumenta","diminuisce","resta costante","si annulla","diventa negativa"],e:"ΔS = Q/T > 0: il liquido è più disordinato del solido.",h:"ΔS = Q/T: durante la fusione il ghiaccio assorbe calore.",x:"Il ghiaccio assorbe calore (Q > 0) e il liquido è più disordinato del solido: l'entropia non può diminuire né restare costante; un'entropia non diventa negativa fondendo."},
{id:"FU521",s:"fis",u:5,q:"La temperatura critica di una sostanza è:",o:["la temperatura sopra cui il gas non si liquefa per sola compressione","la temperatura sotto cui il gas non si liquefa per sola compressione","la temperatura alla quale coesistono solido, liquido e vapore","la temperatura di ebollizione alla pressione di 1 atm","la temperatura minima raggiungibile, cioè lo zero assoluto"],e:"Per l'ossigeno è circa −119 °C: per conservarlo liquido serve raffreddarlo.",h:"Sopra questa temperatura non esiste più distinzione tra liquido e vapore.",x:"Sotto la temperatura critica un gas si può liquefare comprimendolo; la coesistenza di tre stati è il punto triplo; l'ebollizione a 1 atm e lo zero assoluto sono altre temperature."},
{id:"FU522",s:"fis",u:5,q:"Un ciclo termodinamico percorso in senso orario nel piano P-V corrisponde a:",o:["una macchina termica, con lavoro netto positivo","una macchina frigorifera, con lavoro netto negativo","una macchina termica, con lavoro netto nullo","una trasformazione isoterma reversibile","una macchina frigorifera, con lavoro netto positivo"],e:"Il lavoro netto è l'area racchiusa dal ciclo; in senso antiorario il ciclo descrive una macchina frigorifera.",h:"In senso orario l'espansione avviene a pressione maggiore della compressione: il gas compie più lavoro di quanto ne riceve.",x:"Il verso antiorario corrisponde a una macchina frigorifera; un ciclo che racchiude un'area non ha lavoro nullo; un'isoterma non è un ciclo chiuso."},

// ---- Unità 7 (+7 MC)
{id:"FU701",s:"fis",u:7,q:"Un'onda elettromagnetica è formata da:",o:["un campo elettrico e uno magnetico oscillanti, perpendicolari tra loro e alla propagazione","un campo elettrico e uno magnetico oscillanti, paralleli tra loro e alla propagazione","un campo elettrico oscillante parallelo alla direzione di propagazione, senza campo magnetico","particelle cariche che si muovono nella direzione di propagazione","onde di pressione che si propagano anche nel vuoto"],e:"È un'onda trasversale che si propaga anche nel vuoto.",h:"Le onde elettromagnetiche sono trasversali e si propagano anche nel vuoto.",x:"I campi paralleli alla propagazione renderebbero l'onda longitudinale; il campo magnetico c'è sempre; non sono particelle cariche né onde di pressione (queste non esistono nel vuoto)."},
{id:"FU703",s:"fis",u:7,q:"La radiazione ultravioletta può danneggiare il DNA della pelle perché:",o:["i suoi fotoni hanno energia sufficiente a formare dimeri di timina","riscalda la pelle oltre i 100 °C, denaturando il DNA","è una radiazione corpuscolare formata da particelle α","i suoi fotoni hanno energia minore di quelli della luce visibile","rompe il DNA per effetto meccanico, come gli ultrasuoni"],e:"Per questo l'esposizione eccessiva agli UV aumenta il rischio di tumori cutanei.",h:"I fotoni UV hanno più energia di quelli visibili: abbastanza da alterare i legami del DNA.",x:"Gli UV non scaldano la pelle a 100 °C; non sono particelle α; i loro fotoni sono più energetici del visibile, non meno; non agiscono meccanicamente come gli ultrasuoni."},
{id:"FU704",s:"fis",u:7,q:"Le microonde scaldano i cibi perché:",o:["fanno oscillare le molecole d'acqua, che sono dipoli","ionizzano gli atomi del cibo liberando energia","provocano reazioni nucleari nelle molecole d'acqua","fanno oscillare le molecole di grasso, che sono apolari","emettono raggi X che vengono assorbiti dal cibo"],e:"Le microonde non sono ionizzanti.",h:"La molecola d'acqua è polare: il campo elettrico oscillante la fa ruotare avanti e indietro.",x:"Le microonde non sono ionizzanti e non provocano reazioni nucleari; i grassi apolari non rispondono al campo; il forno non emette raggi X."},
{id:"FU705",s:"fis",u:7,q:"Nella radiografia le ossa appaiono chiare perché:",o:["assorbono i raggi X più dei tessuti molli","assorbono i raggi X meno dei tessuti molli","riflettono i raggi X verso la sorgente","emettono raggi X per fluorescenza","sono trasparenti ai raggi X"],e:"Il calcio, con numero atomico più alto, attenua di più i raggi X.",h:"Nella lastra chiaro significa che arrivano pochi raggi X: qualcosa li ha fermati.",x:"Se le ossa assorbissero meno o fossero trasparenti apparirebbero scure; le ossa non riflettono raggi X verso la sorgente né li emettono."},
{id:"FU706",s:"fis",u:7,q:"L'angolo limite per la riflessione totale nel passaggio vetro (n = 1,5) → aria vale circa:",o:["42°","30°","60°","90°","15°"],e:"sen θₗ = 1/1,5 ≈ 0,67 → θₗ ≈ 42°.",h:"sen θ_limite = n₂/n₁ = 1/1,5 ≈ 0,67.",x:"sen 30° = 0,5 e sen 60° ≈ 0,87 non corrispondono a 0,67; 90° vale solo per indici uguali; 15° è troppo piccolo."},
{id:"FU707",s:"fis",u:7,q:"Uno specchio piano forma un'immagine:",o:["virtuale, diritta e uguale all'oggetto","reale, capovolta e uguale all'oggetto","virtuale, capovolta e rimpicciolita","reale, diritta e ingrandita","virtuale, diritta e rimpicciolita"],e:"L'immagine si trova dietro lo specchio, alla stessa distanza dell'oggetto.",h:"Guardati allo specchio: l'immagine sta 'dietro' lo specchio, non è capovolta e ha le tue dimensioni.",x:"Uno specchio piano non forma immagini reali (non si possono proiettare su uno schermo), non capovolge in verticale e non ingrandisce né rimpicciolisce."}
);
BANK.push(
{id:"FUF01",s:"fis",u:1,q:"Un angolo di 180° espresso in radianti vale …… (usa 3,14 per π)",c:["3,14","3.14","pi","π"],n:3.14,tol:0.01,e:"180° = π rad.",h:"Un angolo piatto (180°) corrisponde a π radianti."},
{id:"FUF02",s:"fis",u:1,q:"Il numero 0,00450 ha …… cifre significative",c:["3","tre"],n:3,e:"4, 5 e lo zero finale.",h:"Gli zeri iniziali non sono significativi; gli zeri finali dopo la virgola sì."},
{id:"FUF03",s:"fis",u:1,q:"Il modulo del vettore di componenti (9, 12) è ……",c:["15","quindici"],n:15,e:"√(81 + 144) = 15.",h:"Modulo = √(x² + y²)."},
{id:"FUF04",s:"fis",u:1,q:"Il prefisso 'pico' corrisponde a un fattore 10^……",c:["-12","−12"],n:-12,e:"pico = 10⁻¹².",h:"Prefissi piccoli: milli −3, micro −6, nano −9, pico…"},
{id:"FUF05",s:"fis",u:1,q:"Una densità di 2,7 g/cm³ corrisponde a …… kg/m³",c:["2700","2.700"],n:2700,e:"Si moltiplica per 1000.",h:"1 g/cm³ = 1000 kg/m³."},
{id:"FUF06",s:"fis",u:1,q:"Il prodotto 5·10³ × 4·10⁻⁵ vale …… (scrivi il numero decimale)",c:["0,2","0.2","2·10^-1","2e-1"],n:0.2,e:"20·10⁻² = 0,2.",h:"Moltiplica i numeri (5 × 4) e somma gli esponenti (3 + (−5))."},
{id:"FUF07",s:"fis",u:1,q:"L'unità di misura SI dell'intensità luminosa è la ……",c:["candela","cd"],e:"Una delle sette unità fondamentali.",h:"Ha lo stesso nome di un oggetto che si accende per far luce."},
{id:"FUF08",s:"fis",u:1,q:"Il prodotto scalare di due vettori antiparalleli di modulo 2 e 7 vale ……",c:["-14","−14"],n:-14,e:"2 × 7 × cos 180°.",h:"Vettori antiparalleli formano un angolo di 180°, e cos 180° = −1."},
{id:"FUF09",s:"fis",u:4,q:"Un'onda con periodo 5 ms ha frequenza …… Hz",c:["200","duecento"],n:200,e:"1/0,005.",h:"f = 1/T, con T in secondi (5 ms = 0,005 s)."},
{id:"FUF10",s:"fis",u:4,q:"Una corda lunga 0,5 m fissa agli estremi ha, nella fondamentale, una lunghezza d'onda di …… m",c:["1","uno"],n:1,e:"λ = 2L.",h:"Nella fondamentale la corda contiene mezza lunghezza d'onda: λ = 2L."},
{id:"FUF11",s:"fis",u:4,q:"Due suoni a 256 Hz e 260 Hz sovrapposti producono battimenti con frequenza di …… Hz",c:["4","quattro"],n:4,e:"Differenza delle frequenze.",h:"La frequenza dei battimenti è la differenza tra le due frequenze."},
{id:"FUF12",s:"fis",u:4,q:"Un'eco torna dopo 2 s (v = 340 m/s). La parete dista …… m",c:["340","trecentoquaranta"],n:340,e:"d = v·t/2.",h:"Il suono va e torna: d = v·t / 2."},
{id:"FUF13",s:"fis",u:4,q:"Un suono con intensità 10⁻⁴ W/m² ha un livello sonoro di …… dB",c:["80","ottanta"],n:80,e:"10·log(10⁻⁴/10⁻¹²) = 80.",h:"β = 10·log(I / 10⁻¹²)."},
{id:"FUF14",s:"fis",u:4,q:"La sovrapposizione di due suoni di frequenza molto vicina produce il fenomeno dei ……",c:["battimenti","battimento"],e:"Variazioni periodiche dell'intensità.",h:"Si sentono come un suono che aumenta e diminuisce di intensità periodicamente; servono per accordare gli strumenti."},
{id:"FUF15",s:"fis",u:4,q:"L'aumento dell'ampiezza di oscillazione quando un sistema è sollecitato alla sua frequenza propria si chiama ……",c:["risonanza"],e:"Esempio: la cassa armonica degli strumenti.",h:"È il fenomeno del bicchiere che si rompe con una nota precisa."},
{id:"FUF16",s:"fis",u:4,q:"La terza armonica di una corda con fondamentale a 100 Hz ha frequenza …… Hz",c:["300","trecento"],n:300,e:"f₃ = 3·f₁.",h:"Armoniche di una corda: fₙ = n·f₁."},
{id:"FUF17",s:"fis",u:5,q:"Una temperatura di 212 °F corrisponde a …… °C",c:["100","cento"],n:100,e:"(212 − 32)·5/9.",h:"T(°C) = (T(°F) − 32) × 5/9."},
{id:"FUF18",s:"fis",u:5,q:"Il principio secondo cui due corpi in equilibrio termico con un terzo sono in equilibrio tra loro è il principio …… della termodinamica",c:["zero","0","zeresimo"],e:"È la base logica del termometro.",h:"Fu aggiunto dopo il primo e il secondo principio, ma è più fondamentale: per questo ha un numero più basso."},
{id:"FUF19",s:"fis",u:5,q:"Il calore latente di vaporizzazione dell'acqua è circa …… kJ/kg",c:["2260","2.260","2250","2257","2300"],n:2260,tol:0.03,e:"A 100 °C e 1 atm.",h:"È circa 5 volte il calore necessario per scaldare l'acqua da 0 a 100 °C (≈ 419 kJ/kg)."}
);
